#!/bin/bash
# SYBNB local dev — API + main app + Eats app, against the DISPOSABLE Neon test DB (not production).
# Generated by Claude 2026-10-15. Stop everything with Ctrl+C.
set -u
cd "$(dirname "$0")"

export DATABASE_URL="${DATABASE_URL:?set DATABASE_URL in your shell (test DB only)}"
export AUTH_SECRET='e2e-test-auth-secret-0123456789abcdef0123456789abcdef'
export PHONE_HASH_SECRET='e2e-test-phone-hash-secret-0123456789abcdef01234567'
export OTP_EXPOSE_FOR_TEST=true
export SYBNB_COUNTRY=syria
export STORAGE_ALLOW_LOCAL=true
export API_PORT=3051
# Dev apps run on 5390/5399 — the API's built-in dev CORS list only knows 3050/5180.
export CORS_ORIGIN='http://127.0.0.1:5390,http://localhost:5390,http://127.0.0.1:5399,http://localhost:5399,http://127.0.0.1:5180,http://localhost:5180'
# Dev OTP: sandbox provider (no real email is sent; OTP_EXPOSE_FOR_TEST returns the code in the response).
export EMAIL_PROVIDER=sandbox

if lsof -iTCP:3051 -sTCP:LISTEN >/dev/null 2>&1; then
  echo "Port 3051 busy — stop that process first (lsof -iTCP:3051 -sTCP:LISTEN)"; exit 1
fi

echo "== prisma generate + migrate deploy (Menu Studio 067) =="
npx prisma generate || { echo "PRISMA GENERATE FAILED"; exit 1; }
npx prisma migrate deploy || { echo "MIGRATE FAILED"; exit 1; }

echo "== seeding Eats demo fixtures =="
node scripts/dev-seed-eats-demo.mjs || { echo "DEMO SEED FAILED"; exit 1; }

echo "== starting API (3051) + main app (5390) + Eats app (5399) =="
node server/index.mjs > /tmp/sybnb-dev-api.log 2>&1 &
API_PID=$!
npx vite --host 127.0.0.1 --port 5390 --strictPort > /tmp/sybnb-dev-main.log 2>&1 &
MAIN_PID=$!
npx vite --config apps/se/vite.config.ts > /tmp/sybnb-dev-se.log 2>&1 &
SE_PID=$!
trap 'kill $API_PID $MAIN_PID $SE_PID 2>/dev/null' EXIT

sleep 4
# Verify all three actually came up (strict ports: a busy port = hard failure, never a silent move).
sleep 6
for probe in "3051:/api/health:API" "5390::main app" "5399::Eats app"; do
  port="${probe%%:*}"; rest="${probe#*:}"; path="${rest%%:*}"; name="${rest#*:}"
  if ! curl -s -o /dev/null "http://127.0.0.1:${port}${path}"; then
    echo "FAILED to start: ${name} (port ${port}). Logs: /tmp/sybnb-dev-api.log /tmp/sybnb-dev-main.log /tmp/sybnb-dev-se.log"
    exit 1
  fi
done

echo ""
echo "  Open these in your browser:"
echo "    Eats customer app:    http://127.0.0.1:5399"
echo "    Merchant dashboard:   http://127.0.0.1:5390/#/merchant"
echo "    Driver dashboard:     http://127.0.0.1:5390/#/driver   (deliveries panel inside)"
echo ""
echo "  Test DB — sign up with any email; the code appears in the dev response."
echo "  Ctrl+C here stops all three."
wait
